<script setup>
import { computed, ref } from 'vue';
import { REPORT_STATIONS, createReportRows, isoToday } from '../rainfall-report.js';
import { recordAudit } from '../audit-log.js';
import RainfallTable from './RainfallReportTable.vue';

const props = defineProps({ theme: { type: String, default: 'dark' } });
const STORE = 'ndwc.sensor.rainfall-report-profiles.v1';
const today = isoToday();
const profileSearch = ref('');
const referenceDate = ref(today);
const screen = ref('overview');
const activeId = ref(null);
const deleting = ref(null);
const notice = ref('');
const step = ref(1);
const stationQuery = ref('');
const provinceFilter = ref('');
const agencyFilter = ref('');
const typeFilter = ref('all');
function blankForm(){ return { id:'',name:'',description:'',provinces:[],agencies:[],stationIds:REPORT_STATIONS.filter(x=>x.scope==='project').slice(0,3).map(x=>x.id) }; }
const form = ref(blankForm());
function seeds(){ return [{ id:'rainfall-daily',name:'รายงานปริมาณฝนประจำวัน',description:'สรุปสถานีในโครงการ ปภ. สำหรับติดตามรายวัน',provinces:['น่าน','จันทบุรี'],agencies:['กรมป้องกันและบรรเทาสาธารณภัย','กรมทรัพยากรน้ำ'],stationIds:['G15006-5501','G15006-0512','G15006-0515','G15006-2201','G15006-2202'],createdAt:today,updatedAt:today }]; }
function loadProfiles(){ try { const stored=JSON.parse(localStorage.getItem(STORE)); return Array.isArray(stored)&&stored.length?stored:seeds(); } catch { return seeds(); } }
const profiles = ref(loadProfiles());
function persist(){ localStorage.setItem(STORE,JSON.stringify(profiles.value)); }
const activeProfile = computed(()=>profiles.value.find(x=>x.id===activeId.value)||profiles.value[0]||null);
const filteredProfiles = computed(()=>{ const q=profileSearch.value.trim().toLocaleLowerCase('th-TH'); return profiles.value.filter(x=>!q||[x.name,x.description,...x.provinces,...x.agencies].join(' ').toLocaleLowerCase('th-TH').includes(q)); });
const rows = computed(()=>activeProfile.value?createReportRows(activeProfile.value.stationIds):[]);
const provinces = computed(()=>[...new Set(REPORT_STATIONS.map(x=>x.province))]);
const agencies = computed(()=>[...new Set(REPORT_STATIONS.map(x=>x.agency))]);
const filteredStations = computed(()=>{ const q=stationQuery.value.trim().toLocaleLowerCase('th-TH'); return REPORT_STATIONS.filter(x=>(!provinceFilter.value||x.province===provinceFilter.value)&&(!agencyFilter.value||x.agency===agencyFilter.value)&&(typeFilter.value==='all'||x.scope===typeFilter.value)&&(!q||[x.code,x.name,x.amphoe,x.province,x.agency].join(' ').toLocaleLowerCase('th-TH').includes(q))); });
const selectedStations = computed(()=>REPORT_STATIONS.filter(x=>form.value.stationIds.includes(x.id)));
const allFilteredSelected = computed(()=>filteredStations.value.length&&filteredStations.value.every(x=>form.value.stationIds.includes(x.id)));
const invalid = computed(()=>!form.value.name.trim()||!form.value.stationIds.length);
function dateLabel(iso,offset=0){ const d=new Date(`${iso}T00:00:00`);d.setDate(d.getDate()+offset);return new Intl.DateTimeFormat('th-TH',{day:'2-digit',month:'short',year:'numeric'}).format(d); }
function openCreate(){ form.value=blankForm();step.value=1;screen.value='form'; }
function openEdit(profile){ form.value={...profile,provinces:[...profile.provinces],agencies:[...profile.agencies],stationIds:[...profile.stationIds]};step.value=1;screen.value='form'; }
function selectProfile(profile){ activeId.value=profile.id;screen.value='overview'; }
function toggleStation(id){ const ids=new Set(form.value.stationIds);ids.has(id)?ids.delete(id):ids.add(id);form.value.stationIds=[...ids]; }
function toggleAll(){ const ids=new Set(form.value.stationIds);allFilteredSelected.value?filteredStations.value.forEach(x=>ids.delete(x.id)):filteredStations.value.forEach(x=>ids.add(x.id));form.value.stationIds=[...ids]; }
function toggleValue(key,value){ const values=new Set(form.value[key]);values.has(value)?values.delete(value):values.add(value);form.value[key]=[...values]; }
function reportAuditFields(profile){return {stationCount:`${profile.stationIds.length} สถานี`,reportPeriod:'รายวัน · ฝน 3 วัน',status:'ใช้งาน'};}
function save(){ if(invalid.value){notice.value='กรอกชื่อรายงานและเลือกสถานีอย่างน้อย 1 สถานีก่อนบันทึก';step.value=!form.value.name.trim()?1:2;return;} const index=profiles.value.findIndex(x=>x.id===form.value.id);const profile={...form.value,id:form.value.id||`rainfall-${Date.now()}`,name:form.value.name.trim(),description:form.value.description.trim(),stationIds:[...new Set(form.value.stationIds)],createdAt:index>=0?profiles.value[index].createdAt:today,updatedAt:today};if(index>=0)profiles.value.splice(index,1,profile);else profiles.value.unshift(profile);persist();activeId.value=profile.id;screen.value='overview';notice.value=index>=0?'บันทึกการแก้ไข Profile แล้ว':'สร้าง Report Profile แล้ว';recordAudit?.({item:'รายงานปริมาณน้ำฝน',action:index>=0?'แก้ไข':'เพิ่ม',target:profile.name,basin:'-',detail:`เลือก ${profile.stationIds.length} สถานี`,fields:reportAuditFields(profile)}); }
function remove(){const p=deleting.value;if(!p)return;profiles.value=profiles.value.filter(x=>x.id!==p.id);persist();if(activeId.value===p.id)activeId.value=null;recordAudit?.({item:'รายงานปริมาณน้ำฝน',action:'ลบ',target:p.name,basin:'-',detail:'ลบ Report Profile',fields:reportAuditFields(p)});notice.value=`ลบ “${p.name}” แล้ว`;deleting.value=null;}
function download(profile){activeId.value=profile.id;notice.value='Prototype: Preview ใช้โครงแม่แบบ สสน. แล้ว การส่งออก .xlsx จะเปิดใช้เมื่อเชื่อม Rainfall API และแม่แบบ Excel จริง';}
</script>

<template>
<main class="report-page" :class="theme==='light'?'light':''">
  <nav class="crumb">หน้าแรก <span>›</span> การออกรายงานปริมาณน้ำฝน</nav>
  <header class="head"><div><h1>การออกรายงานปริมาณน้ำฝน</h1><p>สร้าง Profile เพื่อเลือกสถานีครั้งเดียว แล้วเรียกดูรายงานรายวันหรือย้อนหลังได้</p></div><button v-if="screen==='overview'" class="primary" @click="openCreate">+ สร้างรายงาน</button><button v-else class="secondary" @click="screen='overview'">← กลับหน้ารายการ</button></header>
  <p v-if="notice" class="notice" role="status">{{notice}} <button @click="notice=''" aria-label="ปิด">×</button></p>

  <template v-if="screen==='overview'">
    <section class="toolbar"><label>ค้นหา Profile<input v-model="profileSearch" type="search" placeholder="ชื่อรายงาน พื้นที่ หรือหน่วยงาน"></label><label>วันที่อ้างอิงรายงาน<input v-model="referenceDate" type="date"></label><small>ข้อมูลจำลองจนกว่าจะเชื่อม Station Master และ Rainfall API</small></section>
    <section class="profiles"><article v-for="profile in filteredProfiles" :key="profile.id" class="profile" :class="{active:activeProfile?.id===profile.id}"><div><small>REPORT PROFILE</small><h2>{{profile.name}}</h2><p>{{profile.description||'ไม่มีคำอธิบาย'}}</p></div><dl><div><dt>พื้นที่</dt><dd>{{profile.provinces.length?profile.provinces.join(', '):'ทุกจังหวัด'}}</dd></div><div><dt>หน่วยงาน</dt><dd>{{profile.agencies.length?profile.agencies.join(', '):'ทุกหน่วยงาน'}}</dd></div><div><dt>สถานี</dt><dd>{{profile.stationIds.length}} สถานี</dd></div></dl><footer><button @click="selectProfile(profile)">ดูรายงาน</button><button @click="openEdit(profile)">แก้ไข</button><button @click="download(profile)">ดาวน์โหลด Excel</button><button class="danger" @click="deleting=profile">ลบ</button></footer></article><p v-if="!filteredProfiles.length" class="empty">ไม่พบ Report Profile ที่ตรงกับการค้นหา</p></section>
    <section v-if="activeProfile" class="preview"><header><div><small>ตัวอย่างรายงาน · ข้อมูลจำลอง</small><h2>{{activeProfile.name}}</h2><p>อ้างอิงวันที่ {{dateLabel(referenceDate)}}</p></div><button class="secondary" @click="download(activeProfile)">ดาวน์โหลด Excel</button></header><RainfallTable :rows="rows" :reference-date="referenceDate"/><footer>โครงสร้างตารางอ้างอิงชีต <b>ฝน 3 วัน</b> จากไฟล์ สสน (1).xlsx — ค่า “ไม่มีข้อมูล” ไม่ถูกแทนด้วย 0</footer></section>
  </template>

  <section v-else class="wizard">
    <ol class="steps"><li :class="{active:step===1,done:step>1}"><b>1</b>ข้อมูลรายงาน</li><li :class="{active:step===2,done:step>2}"><b>2</b>พื้นที่และสถานี</li><li :class="{active:step===3}"><b>3</b>ตรวจสอบรายงาน</li></ol>
    <section v-if="step===1" class="form"><h2>ข้อมูลรายงาน</h2><p>ระบบรองรับเฉพาะรายงานปริมาณน้ำฝน จึงไม่มีตัวเลือกประเภท Report</p><label>ชื่อรายงาน <em>*</em><input v-model="form.name" placeholder="เช่น รายงานปริมาณฝนประจำวัน จังหวัดน่าน"></label><label>คำอธิบาย<textarea v-model="form.description" rows="3" placeholder="รายละเอียดเพิ่มเติม (ถ้ามี)"></textarea></label></section>
<section v-else-if="step===2" class="form rr-area-form"><header><div><h2>พื้นที่และรายการสถานี</h2><p>การเปลี่ยนตัวกรองจะไม่ล้างสถานีที่เลือกไว้</p></div><b>{{form.stationIds.length}} สถานีที่เลือก</b></header><div class="filters"><label>จังหวัด<select v-model="provinceFilter"><option value="">ทุกจังหวัด</option><option v-for="x in provinces" :key="x">{{x}}</option></select></label><label>ประเภทสถานี<select v-model="typeFilter"><option value="all">ทั้งหมด</option><option value="project">สถานีในโครงการ</option><option value="external">สถานีหน่วยงานอื่น</option></select></label><label>หน่วยงาน<select v-model="agencyFilter"><option value="">ทุกหน่วยงาน</option><option v-for="x in agencies" :key="x">{{x}}</option></select></label><label>ค้นหาสถานี<input v-model="stationQuery" type="search" placeholder="ชื่อหรือรหัสสถานี"></label></div><div class="rr-profile-options"><span>บันทึกพื้นที่และหน่วยงานใน Profile</span><div><button v-for="x in provinces" :key="x" type="button" :class="{on:form.provinces.includes(x)}" @click="toggleValue('provinces',x)">{{x}}</button></div><div><button v-for="x in agencies" :key="x" type="button" :class="{on:form.agencies.includes(x)}" @click="toggleValue('agencies',x)">{{x}}</button></div></div><div class="rr-station-list"><header><b>รายการสถานีตามตัวกรอง</b><button type="button" @click="toggleAll">{{allFilteredSelected?'ยกเลิกการเลือกทั้งหมด':'เลือกทั้งหมด'}}</button></header><button v-for="station in filteredStations" :key="station.id" type="button" class="rr-station-row" :class="{selected:form.stationIds.includes(station.id)}" @click="toggleStation(station.id)"><span class="rr-box" aria-hidden="true">{{form.stationIds.includes(station.id)?'✓':''}}</span><span class="rr-station-copy"><b>{{station.name}}</b><small>{{station.code}} · อ.{{station.amphoe}} จ.{{station.province}} · {{station.agency}}</small></span><em :class="station.scope">{{station.scope==='project'?'สถานีในโครงการ':'หน่วยงานอื่น'}}</em></button><p v-if="!filteredStations.length" class="empty">ไม่พบสถานีที่ตรงกับเงื่อนไข</p></div><div class="rr-selected"><b>สถานีที่เลือกแล้ว</b><div><button v-for="x in selectedStations" :key="x.id" @click="toggleStation(x.id)">{{x.name}} <span>×</span></button></div></div></section>
    <section v-else class="form"><h2>ตรวจสอบตัวอย่างรายงาน</h2><p>อ้างอิงตารางจากชีต <b>ฝน 3 วัน</b> ตามไฟล์ สสน (1).xlsx · วันที่ {{dateLabel(referenceDate)}}</p><RainfallTable :rows="createReportRows(form.stationIds)" :reference-date="referenceDate"/></section>
    <footer class="wizard-foot"><button v-if="step>1" class="secondary" @click="step--">กลับ</button><span></span><button v-if="step<3" class="primary" @click="step++">ถัดไป</button><button v-else class="primary" :disabled="invalid" @click="save">บันทึก Profile</button></footer>
  </section>
  <div v-if="deleting" class="overlay" @click.self="deleting=null"><section class="confirm" role="dialog" aria-modal="true"><h2>ยืนยันการลบ Report Profile</h2><p>ต้องการลบ “{{deleting.name}}” ใช่หรือไม่? การลบจะไม่กระทบข้อมูลสถานีและข้อมูลตรวจวัดย้อนหลัง</p><footer><button class="secondary" @click="deleting=null">ยกเลิก</button><button class="delete" @click="remove">ยืนยันการลบ</button></footer></section></div>
</main>
</template>

<style scoped>
